        string path="Assets/ScriptableObjects/Earthquakes/"+file+".asset";var p=AssetDatabase.LoadAssetAtPath<EarthquakeProfile>(path);if(p==null){p=ScriptableObject.CreateInstance<EarthquakeProfile>();AssetDatabase.CreateAsset(p,path);}
        var so=new SerializedObject(p);so.FindProperty("<DisplayName>k__BackingField").stringValue=display;so.FindProperty("<Duration>k__BackingField").floatValue=duration;so.FindProperty("<PreparationCountdown>k__BackingField").floatValue=3f;so.FindProperty("<CameraShakeIntensity>k__BackingField").floatValue=shake;so.FindProperty("<TargetSeconds>k__BackingField").floatValue=target;var curve=new AnimationCurve(new Keyframe(0,0),new Keyframe(.2f,.28f),new Keyframe(.48f,.82f),new Keyframe(.62f,1),new Keyframe(.82f,.48f),new Keyframe(1,0));foreach(string field in new[]{"<IntensityCurve>k__BackingField","<CameraShakeCurve>k__BackingField","<AudioVolumeCurve>k__BackingField","<LightFlickerCurve>k__BackingField","<DustEmissionCurve>k__BackingField","<PropForceCurve>k__BackingField"})so.FindProperty(field).animationCurveValue=curve;so.FindProperty("<MaximumPropForce>k__BackingField").floatValue=2.2f;so.FindProperty("<AudioIntensity>k__BackingField").floatValue=.72f;so.FindProperty("<LightFlickerIntensity>k__BackingField").floatValue=.24f;so.FindProperty("<MaximumDustEmission>k__BackingField").floatValue=6f;so.FindProperty("<MaximumActivePhysicsProps>k__BackingField").intValue=5;so.ApplyModifiedPropertiesWithoutUndo();
    }

