    private static EarthquakeReactiveProp[] BuildEarthquakeProps(){var specs=new[]{("ReactiveChair",new Vector3(5,.45f,3.25f),new Vector3(.65f,.9f,.65f)),("ReactiveSupplyBox",new Vector3(-5,.35f,-.85f),new Vector3(.75f,.7f,.75f)),("ReactiveShelfObject",new Vector3(5.15f,.3f,1.55f),new Vector3(.45f,.6f,.45f)),("ReactiveHangingLamp",new Vector3(5.2f,3.1f,-.7f),new Vector3(.55f,.35f,.55f)),("ReactiveEmergencyCanister",new Vector3(-5.3f,.45f,3.55f),new Vector3(.42f,.9f,.42f))};var list=new List<EarthquakeReactiveProp>();foreach(var spec in specs){var go=Cube(spec.Item1,spec.Item2,spec.Item3,spec.Item1.Contains("Emergency")?dangerMat:metalMat);var body=go.AddComponent<Rigidbody>();body.mass=.8f;body.isKinematic=true;body.useGravity=true;body.maxLinearVelocity=2.2f;body.maxAngularVelocity=6f;var detail=Cube("ReactiveDetail",spec.Item2+new Vector3(0,spec.Item3.y*.55f,0),new Vector3(spec.Item3.x*.65f,.08f,spec.Item3.z*.65f),accentMat);detail.transform.SetParent(go.transform);UnityEngine.Object.DestroyImmediate(detail.GetComponent<Collider>());list.Add(go.AddComponent<EarthquakeReactiveProp>());}return list.ToArray();}
    private static AudioSource EarthquakeAudio(GameObject parent,string name,bool loop){var source=parent.AddComponent<AudioSource>();source.playOnAwake=false;source.loop=loop;source.spatialBlend=0;source.volume=0;return source;}
    private static ParticleSystem EarthquakeDebris(Vector3 pos){var ps=Dust(pos,new Vector3(9,.25f,6),18);ps.name="CeilingDebris";var main=ps.main;main.startLifetime=new ParticleSystem.MinMaxCurve(1.2f,2.4f);main.startSpeed=new ParticleSystem.MinMaxCurve(.1f,.45f);main.gravityModifier=.18f;main.startSize=new ParticleSystem.MinMaxCurve(.02f,.06f);main.maxParticles=28;var emission=ps.emission;emission.rateOverTime=0;return ps;}
    private static ParticleSystem Dust(Vector3 pos,Vector3 box,int count){var g=new GameObject("AtmosphericDust");g.transform.position=pos;var ps=g.AddComponent<ParticleSystem>();var main=ps.main;main.maxParticles=Mathf.Min(count,60);main.startLifetime=6;main.startSpeed=.08f;main.startSize=new ParticleSystem.MinMaxCurve(.025f,.065f);main.startColor=new Color(.7f,.62f,.5f,.16f);main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=ps.emission;emission.rateOverTime=Mathf.Min(count/8f,7f);var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=box;shape.position=new Vector3(0,.5f,2f);var renderer=g.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=vfxMat;renderer.maxParticleSize=.025f;return ps;}
    private static void AddSettings(GameObject panel,FirstPersonController fpc){Text("SensitivityLabel",panel.transform,"SENSIBILIDAD",15,new Vector2(.24f,.31f),new Vector2(250,28),Color.white,FontStyles.Bold);var sens=SliderObj("SensitivitySlider",panel.transform,new Vector2(.53f,.31f),.25f,3f,1f);var sv=Text("SensitivityValue",panel.transform,"1.00",16,new Vector2(.82f,.31f),new Vector2(90,30),Cyan,FontStyles.Bold);Text("VolumeLabel",panel.transform,"VOLUMEN GENERAL",15,new Vector2(.24f,.18f),new Vector2(250,28),Color.white,FontStyles.Bold);var vol=SliderObj("VolumeSlider",panel.transform,new Vector2(.53f,.18f),0,1,1);var vv=Text("VolumeValue",panel.transform,"100%",16,new Vector2(.82f,.18f),new Vector2(90,30),Cyan,FontStyles.Bold);var toggleRoot=ImageObj("ResearchToggle",panel.transform,new Vector2(.19f,.075f),new Vector2(30,30),new Color(.055f,.1f,.13f,1));var check=ImageObj("Checkmark",toggleRoot.transform,new Vector2(.5f,.5f),new Vector2(18,18),Cyan).GetComponent<Image>();var toggle=toggleRoot.AddComponent<Toggle>();toggle.targetGraphic=toggleRoot.GetComponent<Image>();toggle.graphic=check;toggle.isOn=PlayerPrefs.GetInt(SimulationSession.ResearchEnabledKey,0)==1;Text("ResearchLabel",panel.transform,"GUARDAR DATOS ANÓNIMOS DEL SIMULACRO",12,new Vector2(.5f,.09f),new Vector2(520,24),Color.white,FontStyles.Bold);var explanation=Text("ResearchExplanation",panel.transform,"No se sube información; los archivos permanecen en este dispositivo.",10,new Vector2(.5f,.035f),new Vector2(590,24),new Color(.65f,.75f,.78f));var settings=panel.AddComponent<GameplaySettingsController>();Set(settings,"controller",fpc);Set(settings,"sensitivitySlider",sens);Set(settings,"volumeSlider",vol);Set(settings,"sensitivityValue",sv);Set(settings,"volumeValue",vv);Set(settings,"researchToggle",toggle);Set(settings,"researchExplanation",explanation);}
    private static Slider SliderObj(string name,Transform parent,Vector2 anchor,float min,float max,float value){var root=ImageObj(name,parent,anchor,new Vector2(360,28),new Color(.055f,.1f,.13f,1));var fillArea=Rect("Fill Area",root.transform,new Vector2(0,0),new Vector2(1,1));var fr=(RectTransform)fillArea.transform;fr.offsetMin=new Vector2(14,8);fr.offsetMax=new Vector2(-14,-8);var fill=ImageObj("Fill",fillArea.transform,new Vector2(.5f,.5f),new Vector2(332,12),Cyan);fill.GetComponent<Image>().raycastTarget=false;var handleArea=Rect("Handle Slide Area",root.transform,new Vector2(0,0),new Vector2(1,1));var hr=(RectTransform)handleArea.transform;hr.offsetMin=new Vector2(14,0);hr.offsetMax=new Vector2(-14,0);var handle=ImageObj("Handle",handleArea.transform,new Vector2(.5f,.5f),new Vector2(26,26),Color.white);var outline=handle.AddComponent<Outline>();outline.effectColor=Cyan;outline.effectDistance=new Vector2(2,-2);var slider=root.AddComponent<Slider>();slider.fillRect=(RectTransform)fill.transform;slider.handleRect=(RectTransform)handle.transform;slider.targetGraphic=handle.GetComponent<Image>();slider.direction=Slider.Direction.LeftToRight;slider.minValue=min;slider.maxValue=max;slider.value=value;return slider;}

    private static void SetObjectives(ObjectivesManager manager,bool l2)
    {
        var list=l2?new[]{new Objective(GameIds.Level02CollectRadio,"Encuentra la radio de emergencia."),new Objective(GameIds.Level02CollectAccessKey,"Encuentra la llave de acceso."),new Objective(GameIds.Level02ActivateBeacon,"Activa la baliza de emergencia."),new Objective(GameIds.Level02ReachSafeZone,"Llega a la zona segura.")}:new[]{new Objective(GameIds.Level01Preparation,"Prepárate para el inicio del simulacro."),new Objective(GameIds.Level01Protect,"Protégete durante el sismo."),new Objective(GameIds.Level01ExitRoom,"Sal de la habitación."),new Objective(GameIds.Level01CollectBackpack,"Encuentra la mochila de emergencia."),new Objective(GameIds.Level01ActivateEvacuation,"Activa la salida de evacuación."),new Objective(GameIds.Level01ReachExit,"Dirígete al punto de salida.")};
        var so=new SerializedObject(manager);var p=so.FindProperty("objectives");p.arraySize=list.Length;for(int i=0;i<list.Length;i++){var e=p.GetArrayElementAtIndex(i);e.FindPropertyRelative("id").stringValue=list[i].Id;e.FindPropertyRelative("description").stringValue=list[i].Description;}so.ApplyModifiedPropertiesWithoutUndo();
    }
    private static InventorySlotView InventorySlot(Transform parent,string objectName,string id,string label,string spritePath,float x){var slot=Panel(objectName,parent,new Vector2(x,.47f),new Vector2(145,72));slot.GetComponent<Image>().raycastTarget=false;var accent=slot.GetComponent<Image>();var icon=ImageObj("Icon",slot.transform,new Vector2(.24f,.56f),new Vector2(40,40),new Color(.32f,.38f,.42f,.65f)).GetComponent<Image>();icon.raycastTarget=false;icon.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(spritePath);icon.preserveAspect=true;var name=Text("ItemName",slot.transform,label,11,new Vector2(.63f,.42f),new Vector2(84,34),new Color(.65f,.7f,.73f,1),FontStyles.Bold);name.raycastTarget=false;var check=Text("CheckMark",slot.transform,"✓",20,new Vector2(.88f,.78f),new Vector2(28,28),new Color(.15f,1f,.7f),FontStyles.Bold).gameObject;var view=slot.AddComponent<InventorySlotView>();Set(view,"itemId",id);Set(view,"icon",icon);Set(view,"itemName",name);Set(view,"checkMark",check);Set(view,"accent",accent);view.SetObtained(false);return view;}
