    private static Button ButtonAt(string name,Transform parent,string label,Vector2 anchor,UnityEngine.Events.UnityAction action){var b=ButtonObj(name,parent,label,anchor,action);((RectTransform)b.transform).sizeDelta=new Vector2(360,64);return b;}
    private static void SetArray(UnityEngine.Object target,string property,Component[] values){var so=new SerializedObject(target);var p=so.FindProperty(property);p.arraySize=values.Length;for(int i=0;i<values.Length;i++)p.GetArrayElementAtIndex(i).objectReferenceValue=values[i];so.ApplyModifiedPropertiesWithoutUndo();}
    private static void WirePauseButtons(GameObject p,PauseController c){Wire(p,"ResumeButton",c.Resume);Wire(p,"RestartButton",c.Reload);Wire(p,"MenuButton",c.MainMenu);}
    private static void WireCompletionButtons(GameObject p,GameCompletionController c){Wire(p,"RestartButton",c.RestartCurrentLevel);Wire(p,"MenuButton",c.ReturnToMainMenu);Wire(p,"ExitButton",c.QuitGame);}
    private static void Wire(GameObject root,string name,UnityEngine.Events.UnityAction action){var b=Find(root.transform,name).GetComponent<Button>();b.onClick.RemoveAllListeners();UnityEventTools.AddPersistentListener(b.onClick,action);}

    private static void PrepareScene(string path){if(File.Exists(path))EditorSceneManager.OpenScene(path,OpenSceneMode.Single);else EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects()){if(root.name=="Generated_GuardianMisti"||root.name=="SimulationSession"||IsLegacyGeneratedRoot(root.name))UnityEngine.Object.DestroyImmediate(root);}}
    private static bool IsLegacyGeneratedRoot(string n)=>new[]{"Main Camera","EventSystem","App","Canvas","GameplayHUD","GameplayPlayer","GameplaySystems","GameplayCursorController","Directional Light","Ground","LeftWall","RightWall","InitialDoor","EmergencyBackpack","EvacuationTerminal","LevelExit","EmergencyRadio","AccessKey","EmergencyBeacon","SafeZone","EVACUACIÓN","ZONA SEGURA"}.Contains(n);
    private static void ConsolidateGenerated(GameObject generated){foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects())if(root!=generated&&root.GetComponent<SimulationSession>()==null)root.transform.SetParent(generated.transform,true);}
    private static void SaveScene(string path){EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),path);}
    private static void EventSystem(){var e=new GameObject("EventSystem");e.AddComponent<EventSystem>();e.AddComponent<InputSystemUIInputModule>();}
