    private static Button ButtonObj(string name,Transform parent,string label,Vector2 anchor,UnityEngine.Events.UnityAction action){var g=ImageObj(name,parent,anchor,new Vector2(420,68),new Color(.04f,.34f,.44f,.96f));var b=g.AddComponent<Button>();var colors=b.colors;colors.normalColor=Color.white;colors.highlightedColor=new Color(1.12f,1.12f,1.12f,1);colors.pressedColor=new Color(.72f,.9f,.94f,1);colors.selectedColor=colors.highlightedColor;colors.disabledColor=new Color(.45f,.45f,.45f,.5f);b.colors=colors;var t=Text("Label",g.transform,label,20,new Vector2(.5f,.5f),new Vector2(400,60),Color.white,FontStyles.Bold);t.raycastTarget=false;if(action!=null)UnityEventTools.AddPersistentListener(b.onClick,action);return b;}
    private static GameObject Cube(string name,Vector3 pos,Vector3 scale,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.position=pos;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;return g;}
    private static void TextWorld(string text,Vector3 pos,Color color){var g=new GameObject(text);g.transform.position=pos;g.transform.rotation=Quaternion.Euler(0,180,0);var t=g.AddComponent<TextMeshPro>();t.text=text;t.fontSize=3;t.alignment=TextAlignmentOptions.Center;t.color=color;}
    private static Transform Find(Transform root,string name){foreach(Transform t in root.GetComponentsInChildren<Transform>(true))if(t.name==name)return t;throw new Exception($"Missing child {name}");}
    private static void Set(UnityEngine.Object target,string property,object value){var so=new SerializedObject(target);var p=so.FindProperty(property);if(p==null)throw new Exception($"{target.GetType().Name}.{property} not serialized");switch(value){case UnityEngine.Object o:p.objectReferenceValue=o;break;case string s:p.stringValue=s;break;case bool b:p.boolValue=b;break;case float f:p.floatValue=f;break;case Behaviour[] a:p.arraySize=a.Length;for(int i=0;i<a.Length;i++)p.GetArrayElementAtIndex(i).objectReferenceValue=a[i];break;default:throw new Exception($"Unsupported serialized value {value?.GetType()}");}so.ApplyModifiedPropertiesWithoutUndo();}
